definition:
[
  base/.style={draw,thick,minimum width=22mm,minimum height=9mm,align=center},
  ok/.style={base,fill=green!20,rounded corners},
  warn/.style={base,fill=yellow!35,double},
  bad/.style={base,fill=red!25,dashed},
  flow/.style={-{Stealth},thick,gray!60!black}
]
\node[ok]   (a) at (0,2)   {healthy};
\node[warn] (b) at (0,0.8) {degraded};
\node[bad]  (c) at (0,-0.4){failed};
\node[base] (d) at (4,0.8) {monitor};
\draw[flow] (a) -- (d);
\draw[flow] (b) -- (d);
\draw[flow] (c) -- (d);
